#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled Conv2d forward kernel (CuTe).
// Each block handles a tile of output spatial positions (Threads * PVec)
// for CcPerBlock output channels of one batch element.
// Weights for the CcPerBlock channels (all C_in*KH*KW taps) are staged in
// shared memory once per block, then reused across all output positions.
template <typename T>
__global__ void conv2d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C_in, int H, int Win,
    int C_out, int KH, int KW,
    int stride, int padding,
    int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 4;
  constexpr int KMax       = 1024; // max C_in*KH*KW supported

  const int tid = threadIdx.x;

  // Block coordinates
  const int n      = blockIdx.z;
  const int c_tile = blockIdx.y;
  const int c_base = c_tile * CcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  const int K = C_in * KH * KW;

  // Memory strides
  const int64_t sXn = (int64_t)C_in * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)C_out * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  // Global tensors using CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C_in, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(C_out, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(C_out, K),
      make_stride((int64_t)K, Int<1>{})
  );

  // Shared memory for weights of CcPerBlock output channels
  __shared__ T sW_raw[CcPerBlock * KMax];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CcPerBlock>{}, Int<KMax>{}),
      make_stride(Int<KMax>{}, Int<1>{})
  );

  // Stage weights into shared memory
  for (int k = tid; k < K; k += Threads) {
    #pragma unroll
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int c = c_base + cc;
      T wval = T(0);
      if (c < C_out) {
        wval = mW(c, k);
      }
      sW(cc, k) = wval;
    }
  }
  __syncthreads();

  // Precompute per-thread output positions
  int  p_idx[PVec];
  int  oh_arr[PVec];
  int  ow_arr[PVec];
  int  ih0_arr[PVec];
  int  iw0_arr[PVec];
  bool valid_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i]    = oh;
      ow_arr[i]    = ow;
      ih0_arr[i]   = oh * stride - padding;
      iw0_arr[i]   = ow * stride - padding;
      valid_arr[i] = true;
    } else {
      oh_arr[i]    = 0;
      ow_arr[i]    = 0;
      ih0_arr[i]   = 0;
      iw0_arr[i]   = 0;
      valid_arr[i] = false;
    }
  }

  // Accumulators initialized with bias
  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (B != nullptr && c < C_out) {
      bval = (float)B[c];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  // Main convolution loop
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    if (!valid_arr[i]) continue;

    const int ih0 = ih0_arr[i];
    const int iw0 = iw0_arr[i];

    for (int ic = 0; ic < C_in; ++ic) {
      for (int kh = 0; kh < KH; ++kh) {
        int ih = ih0 + kh;
        if ((unsigned)ih >= (unsigned)H) continue;

        const int k_row = (ic * KH + kh) * KW;

        for (int kw = 0; kw < KW; ++kw) {
          int iw = iw0 + kw;
          if ((unsigned)iw >= (unsigned)Win) continue;

          float xval = (float)mX(ic, ih, iw);
          int k = k_row + kw;

          #pragma unroll
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            acc[cc][i] += xval * (float)sW(cc, k);
          }
        }
      }
    }
  }

  // Store results
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= C_out) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid_arr[i]) continue;
      mY(c, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C_in, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C_out, C_in, KH, KW]");

  int64_t N     = x.size(0);
  int64_t C_in  = x.size(1);
  int64_t H     = x.size(2);
  int64_t Win   = x.size(3);

  int64_t C_out = w.size(0);
  int64_t KH    = w.size(2);
  int64_t KW    = w.size(3);

  TORCH_CHECK(w.size(1) == C_in, "w.size(1) must equal C_in");
  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t K = C_in * KH * KW;
  TORCH_CHECK(K <= 1024, "C_in*KH*KW must be <= 1024 for this kernel");

  int64_t Hout = (H + 2 * padding - KH) / stride + 1;
  int64_t Wout = (Win + 2 * padding - KW) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C_out, "bias must be [C_out]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, C_out, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 4;
  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((C_out + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_tiled_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C_in, (int)H, (int)Win,
      (int)C_out, (int)KH, (int)KW,
      (int)stride, (int)padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_11x11_s4_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Conv2d(3, 96, kernel_size=11, stride=4, padding=2) implemented with a
    single cooperative tiled CUDA kernel written with CuTe.
    """
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels,
                        self.kernel_size, self.kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size * self.kernel_size
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

