  int  oh_arr[PVec];
  int  ow_arr[PVec];
  int  ih0_arr[PVec];
  int  iw0_arr[PVec];
  bool valid_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
