  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    if (!valid_arr[i]) continue;

    const int ih0 = ih0_arr[i];
    const int iw0 = iw0_arr[i];

    for (int ic = 0; ic < C_in; ++ic) {
      for (int kh = 0; kh < KH; ++kh) {
        int ih = ih0 + kh;
        if ((unsigned)ih >= (unsigned)H) continue;

        const int k_row = (ic * KH + kh) * KW;

        for (int kw = 0; kw < KW; ++kw) {
          int iw = iw0 + kw;
          if ((unsigned)iw >= (unsigned)Win) continue;

          float xval = (float)mX(ic, ih, iw);
          int k = k_row + kw;

          #pragma unroll
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            acc[cc][i] += xval * (float)sW(cc, k);
          }
        }
      }
    }
  }

  // Store results
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= C_out) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid_arr[i]) continue;
      mY(c, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
